function n(t,i=2){const o=Math.abs(t),r=t<0?"-":"";return o>=1e9?`${r}$${(o/1e9).toFixed(2)}B`:o>=1e6?`${r}$${(o/1e6).toFixed(2)}M`:r+new Intl.NumberFormat("en-US",{style:"currency",currency:"USD",minimumFractionDigits:i,maximumFractionDigits:i}).format(o)}function a(t,i=2){return`${t>0?"+":""}${t.toFixed(i)}%`}function c(t){return t>=1e3?t.toLocaleString("en-US",{minimumFractionDigits:2,maximumFractionDigits:2}):t>=1?t.toFixed(4):t.toFixed(6)}function f(t){const i=Date.now()-new Date(t).getTime(),o=Math.floor(i/1e3);if(o<60)return`${o}s ago`;const r=Math.floor(o/60);if(r<60)return`${r}m ago`;const e=Math.floor(r/60);return e<24?`${e}h ago`:`${Math.floor(e/24)}d ago`}export{a,n as b,c as f,f as t};
